using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public sealed partial class DemoWorld {
 public string BuyDenP(){if(!Docked||Balance<2000)return "Dock with 2,000 CR for a deployment kit.";WalletChange(-2000,"Physical den kit");Hangar["p_den"]=Hangar.GetValueOrDefault("p_den")+1;return "";}
 public string DeployDenP(){if(Docked||InWarp||Current.Security>0||InHubH||InTriuneH||InAbyssF||Commander.Capsule||ItemCount("p_den",false)<1||OperationsP.Dens.Count(d=>d.State!="Destroyed")>=5||OperationsP.Dens.Any(d=>d.System==SystemId&&d.State!="Destroyed"&&(d.Anchor-SystemPosition).Length<50000))return "Undock in ordinary null-security space with a real kit; five local dens maximum, 50 km spacing.";ChangeStack("p_den",false,-1);OperationsP.Dens.Add(new(){System=SystemId,Grid=SolarGridKey,Anchor=SystemPosition,Position=Player.Position,Last=Now,Opportunity=Now.AddHours(1)});BindDensP();return "";}
 public void BindDensP(){if(Docked||ActiveEncounterF!=null)return;foreach(var d in OperationsP.Dens.Where(d=>d.System==SystemId&&d.Grid==SolarGridKey&&d.State!="Destroyed")){if(Targets.Any(t=>t.Id=="den-p:"+d.Id))continue;var s=Ship.RaiderProfile();s.SetStat("shieldCapacity",5000);s.SetStat("armorHP",5000);s.SetStat("hp",5000);Targets.Add(new(){Id="den-p:"+d.Id,Name="Owned physical mercenary den / "+d.State,Kind=TargetKind.Raider,Profile=s,Friendly=true,Training=true,Position=(d.Anchor-SolarOrigin).Local,Shield=d.Shield,Armor=d.Armor,Hull=d.Hull,Signature=1000});}}
 public void TickDensP(){foreach(var d in OperationsP.Dens.Where(d=>d.State!="Destroyed")){int hours=(int)Math.Max(0,(Now-d.Last).TotalHours);if(hours>0){d.Last=d.Last.AddHours(hours);d.Output=Math.Min(500,d.Output+hours*(1+d.Development));d.Anarchy=Math.Min(10,d.Anarchy+hours);}if(d.State=="Reinforced"&&d.ReinforcedUntil<=Now)d.State="Online";var t=Targets.FirstOrDefault(t=>t.Id=="den-p:"+d.Id);if(t!=null){d.Shield=t.Shield;d.Armor=t.Armor;d.Hull=t.Hull;}}BindDensP();}
 public void DamageDenP(SpaceTarget t){var d=OperationsP.Dens.FirstOrDefault(d=>"den-p:"+d.Id==t.Id);if(d==null)return;d.Shield=t.Shield;d.Armor=t.Armor;d.Hull=t.Hull;if(t.Shield<=0&&!d.ReinforcedOnce){d.ReinforcedOnce=true;d.State="Reinforced";d.ReinforcedUntil=Now.AddHours(18+StableC(d.Id)%13);t.Armor=Math.Max(1,t.Armor);t.Hull=Math.Max(1,t.Hull);d.Armor=t.Armor;d.Hull=t.Hull;return;}if(t.Hull<=0&&!d.DropSealed){d.DropSealed=true;d.State="Destroyed";Targets.Add(new(){Id="wreck_den-p:"+d.Id,Name="Destroyed den output",Kind=TargetKind.Wreck,Position=t.Position,Contents=new(){{"p_infomorph",d.Output/2}},Salvage=3});d.Output=0;t.KillRecorded=true;}}
 public string ClaimDenP(string id){TickDensP();var d=OperationsP.Dens.FirstOrDefault(d=>d.Id==id);if(d==null||d.Owner!="player"||d.State!="Online"||d.Shield<=2500||d.System!=SystemId||Docked||(d.Anchor-SystemPosition).Length>2500||d.Output<=0)return "Owned online den above half shields within 2,500 m required.";float q=Math.Min(d.Output,MathF.Floor(CargoRoom("p_infomorph")/ItemVolume("p_infomorph")));if(q<=0)return "Cargo hold full.";ChangeStack("p_infomorph",false,(decimal)q);d.Output-=(int)q;return "";}
 public string OpportunityP(string id,string profile){var d=OperationsP.Dens.FirstOrDefault(d=>d.Id==id);var p=CatalogP.Get(profile);if(d==null||d.State!="Online"||d.System!=SystemId||d.Opportunity>Now||p?.Family!="Den"||!CruiserEligibleF)return "Local online den, elapsed cooldown and cruiser required.";string error=IssueP(profile);if(error!="")return error;Exploration.Encounters.Last().Parent=d.Id;d.Opportunity=Now.AddHours(4);return "";}
 public string ExchangeHubP(){if(!Docked||!InHubH||ItemCount("p_infomorph",true)<10)return "At the hub contact deliver ten owned infomorphs.";ChangeStack("p_infomorph",true,-10);Hangar["p_tokens"]=Hangar.GetValueOrDefault("p_tokens")+1;return "";}
}
